for arm,label in [('run-2p1d-80k','2P4 + D8'),('run-1p1d-80k','1P4 + D8, original outputs')]:
 x=results.get(arm)
 if not x:rows.append([label,'In progress','—','—','—','—']);continue
 rows.append([link('http://43.156.43.133:31019/replay/runs/'+x['run_id']+'/report',label),esc(x['state']),num(x['ttft_percentiles_s']['p50'])+' / '+num(x['ttft_percentiles_s']['p99']),num(x['worst_ttft_point']['ttft']['p50']/1000),num(x['tpot_ms']['p99']),str(x['meaningful_requests'])+' / '+str(x['expected_requests'])])
